import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Formular erstellen","description":"Ein Formular auf ein Grid anlegen, Felder hinzufügen und die Erfolgsseite konfigurieren.","frontmatter":{"title":"Formular erstellen","description":"Ein Formular auf ein Grid anlegen, Felder hinzufügen und die Erfolgsseite konfigurieren."},"headers":[],"relativePath":"formulare/formular-erstellen.md","filePath":"formulare/formular-erstellen.md","lastUpdated":1786092153000}'),s={name:"formulare/formular-erstellen.md"};function a(l,e,d,o,u,h){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ihr-erstes-formular" tabindex="-1">Ihr erstes Formular <a class="header-anchor" href="#ihr-erstes-formular" aria-label="Permalink to &quot;Ihr erstes Formular&quot;">​</a></h1><p>Ein <strong>Formular</strong> ist eine Eingabemaske auf ein Grid. Sie bestimmen, welche Felder abgefragt werden, wie das Formular aussieht und was nach dem Absenden passiert.</p><p>Personen, die ein Formular ausfüllen, brauchen <strong>kein ApptiveGrid-Konto</strong> — sofern Sie den Zugriff nicht ausdrücklich beschränken.</p><h2 id="formular-anlegen" tabindex="-1">Formular anlegen <a class="header-anchor" href="#formular-anlegen" aria-label="Permalink to &quot;Formular anlegen&quot;">​</a></h2><ol><li>Öffnen Sie in der Seitenleiste das Grid, in das die Daten laufen sollen.</li><li>Wählen Sie unter <strong>Formulare</strong> die Option <strong>Formular erstellen</strong>.</li><li>Vergeben Sie einen Namen.</li></ol><p>Das Formular ist zunächst leer. Ohne ausgewählte Felder kann niemand etwas eintragen.</p><div class="tip custom-block"><p class="custom-block-title">Ein Formular gehört immer zu einem Grid</p><p>Ein Formular schreibt in genau ein Grid. Sollen Daten in mehrere Grids fließen, brauchen Sie mehrere Formulare — oder Sie lassen einen <a href="/flows/aktionen">Flow</a> die Verteilung übernehmen.</p></div><h2 id="felder-hinzufugen" tabindex="-1">Felder hinzufügen <a class="header-anchor" href="#felder-hinzufugen" aria-label="Permalink to &quot;Felder hinzufügen&quot;">​</a></h2><p>Der Editor hat drei Reiter: <strong>Seiten</strong>, <strong>Layout</strong> und <strong>Mehr</strong>. Die Feldauswahl liegt im Reiter <em>Seiten</em>.</p><p>Links stehen unter <strong>Verfügbare Felder</strong> alle Felder des Grids, die noch nicht im Formular sind.</p><ul><li><strong>Felder Hinzufügen</strong> übernimmt ein vorhandenes Feld ins Formular.</li><li><strong>Feld erstellen</strong> legt ein <em>neues</em> Feld im Grid an und fügt es gleich ein.</li></ul><div class="warning custom-block"><p class="custom-block-title">„Feld erstellen&quot; verändert das Grid</p><p>Diese Schaltfläche legt eine neue Spalte im Grid an — nicht nur etwas im Formular. Die Spalte erscheint danach in allen Ansichten dieses Grids.</p></div><p>Nicht jeder Spaltentyp lässt sich abfragen. <strong>Formatierter Text</strong> sowie die berechneten Typen <strong>Wert übernehmen</strong>, <strong>Summe berechnen</strong> und <strong>Formel</strong> haben kein Formularfeld. Details in der <a href="/referenz/spaltentypen">Spaltentypen-Referenz</a>.</p><h2 id="feldeinstellungen" tabindex="-1">Feldeinstellungen <a class="header-anchor" href="#feldeinstellungen" aria-label="Permalink to &quot;Feldeinstellungen&quot;">​</a></h2><p>Ein Klick auf <strong>Bearbeiten</strong> an einem Feld öffnet die <strong>Feldeinstellungen</strong>:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Label</strong></td><td>Beschriftung im Formular. Überschreibt den Spaltennamen nur für dieses Formular.</td></tr><tr><td><strong>Beschreibung</strong></td><td>Erklärender Text unter der Beschriftung.</td></tr><tr><td><strong>Pflichtfeld</strong></td><td>Das Formular lässt sich ohne Eingabe nicht absenden.</td></tr><tr><td><strong>Mehrzeilig</strong></td><td>Bei Textfeldern: mehrere Zeilen statt einer.</td></tr><tr><td><strong>Komponententyp</strong></td><td>Bei Auswahlfeldern <em>Dropdown-Menü</em> oder <em>Liste</em>; bei Dateien <em>Datei auswählen</em> oder <em>Video aufnehmen</em>.</td></tr><tr><td><strong>Nur Hinzufügen von Dateien erlauben</strong></td><td>Bestehende Anhänge können nicht gelöscht werden.</td></tr><tr><td><strong>Vorausgefüllt</strong></td><td>Ein Standardwert, der beim Öffnen bereits eingetragen ist.</td></tr><tr><td><strong>Nicht änderbar</strong></td><td>Das Feld wird angezeigt, lässt sich aber nicht bearbeiten.</td></tr><tr><td><strong>Nicht sichtbar</strong></td><td>Das Feld wird nicht angezeigt, aber mitgeschickt.</td></tr><tr><td><strong>Barcode-Scanner aktivieren</strong></td><td>Erlaubt das Befüllen per Kamera-Scan.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">„Nicht sichtbar&quot; und „Vorausgefüllt&quot; gehören zusammen</p><p>Ein verstecktes Feld entfaltet seinen Nutzen erst mit einem Wert. Beispiel: Ein verstecktes Feld <em>Quelle</em> wird über einen <a href="/formulare/vorausgefuellte-links">vorausgefüllten Link</a> mit <code>Newsletter</code> befüllt — die ausfüllende Person sieht davon nichts, aber Sie wissen später, woher die Anmeldung kam.</p></div><div class="warning custom-block"><p class="custom-block-title">Versteckte Felder sind nicht vertraulich</p><p><em>Nicht sichtbar</em> blendet ein Feld in der Oberfläche aus. Es ist damit nicht geheim. Legen Sie dort keine Daten hinein, die die ausfüllende Person nicht sehen darf.</p></div><p>Vier dieser Einstellungen sind tarifabhängig: <em>Nicht änderbar</em>, <em>Nicht sichtbar</em>, <em>Vorausgefüllt</em> und <em>Barcode-Scanner aktivieren</em>.</p><h2 id="texte-und-textblocke" tabindex="-1">Texte und Textblöcke <a class="header-anchor" href="#texte-und-textblocke" aria-label="Permalink to &quot;Texte und Textblöcke&quot;">​</a></h2><p>Über dem Formular stehen <strong>Titel des Formulars</strong> und <strong>Beschreibung</strong>.</p><p>Zwischen die Felder setzen Sie mit <strong>Textblock erstellen</strong> erklärende Abschnitte. Ein Textblock ist entweder eine <strong>Überschrift</strong> oder ein <strong>Absatz</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Lange Formulare gliedern</p><p>Überschriften-Textblöcke sind das einfachste Mittel gegen unübersichtliche Formulare. Ab etwa zehn Feldern lohnen sich stattdessen <a href="/formulare/mehrseitige-formulare">mehrere Formularseiten</a>.</p></div><h2 id="erscheinungsbild" tabindex="-1">Erscheinungsbild <a class="header-anchor" href="#erscheinungsbild" aria-label="Permalink to &quot;Erscheinungsbild&quot;">​</a></h2><p>Im Reiter <strong>Layout</strong> stellen Sie ein:</p><ul><li><strong>Texte</strong> — Titel, Beschreibung, <em>Absenden-Button Text</em></li><li><strong>Bilder und Logo</strong> — <em>Hintergrundbild</em> sowie <em>Logo</em> mit <em>Breite</em> (in Prozent der Formularbreite)</li><li><strong>Farben</strong> — <em>Hauptfarbe</em>, <em>Button Farbe</em>, <em>Hintergrundfarbe</em>, <em>Hintergrundfarbe Karte</em>, <em>Farbe Kopfzeile</em>, <em>Karte ohne Schatten</em></li><li><strong>Style der Felder</strong> — <em>Ohne Rahmen</em> oder <em>Mit Rahmen</em></li></ul><div class="tip custom-block"><p class="custom-block-title">Logo ist tarifabhängig</p><p>Ein eigenes Logo steht nur im höchsten Tarif zur Verfügung. Hintergrundbild und Farben sind in allen Tarifen verfügbar.</p></div><h2 id="was-nach-dem-absenden-passiert" tabindex="-1">Was nach dem Absenden passiert <a class="header-anchor" href="#was-nach-dem-absenden-passiert" aria-label="Permalink to &quot;Was nach dem Absenden passiert&quot;">​</a></h2><p>Der Bereich <strong>Erfolgsseite</strong> legt fest, was die ausfüllende Person danach sieht.</p><p>Standardmäßig erscheint <em>Vielen Dank!</em> mit dem Text <em>Ihre Antwort ist bei uns eingegangen.</em> Beides ändern Sie über <strong>Titel</strong> und <strong>Nachricht</strong>.</p><p>Darunter wählen Sie eine <strong>Aktion</strong>:</p><table tabindex="0"><thead><tr><th>Aktion</th><th>Verhalten</th></tr></thead><tbody><tr><td><strong>Keine Aktion</strong></td><td>Es bleibt bei der Erfolgsmeldung.</td></tr><tr><td><strong>Erneut ausfüllen</strong></td><td>Ein Button öffnet das Formular erneut — für mehrere Eingaben hintereinander.</td></tr><tr><td><strong>Auf Webseite weiterleiten</strong></td><td>Weiterleitung auf eine von Ihnen angegebene <strong>Webseite</strong>.</td></tr></tbody></table><p>Bei den letzten beiden bestimmen Sie zusätzlich das <strong>Auslösen durch</strong>:</p><ul><li><strong>Button klicken</strong> — die Person entscheidet</li><li><strong>Direkt nach absenden</strong> — sofort</li><li><strong>nach 5 Sekunden</strong> — die Erfolgsmeldung bleibt kurz stehen</li></ul><div class="tip custom-block"><p class="custom-block-title">Weiterleitung mit Bedacht wählen</p><p><em>Direkt nach absenden</em> überspringt die Erfolgsmeldung vollständig. Die Person sieht dann keine Bestätigung, dass etwas angekommen ist. <em>nach 5 Sekunden</em> ist meist die bessere Wahl.</p></div><p>Die Weiterleitung ist tarifabhängig.</p><h2 id="produkthinweis-ausblenden" tabindex="-1">Produkthinweis ausblenden <a class="header-anchor" href="#produkthinweis-ausblenden" aria-label="Permalink to &quot;Produkthinweis ausblenden&quot;">​</a></h2><p>Formulare tragen standardmäßig den Hinweis <em>Erstell dein eigenes kostenloses Formular mit …</em>. Über <strong>Produkt Hinweis ausblenden</strong> entfernen Sie ihn. Auch das ist tarifabhängig.</p><h2 id="weitere-einstellungen" tabindex="-1">Weitere Einstellungen <a class="header-anchor" href="#weitere-einstellungen" aria-label="Permalink to &quot;Weitere Einstellungen&quot;">​</a></h2><p>Im Reiter <strong>Mehr</strong>:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Zweck</th></tr></thead><tbody><tr><td><strong>Speichern um später fortzufahren</strong></td><td>Ausfüllende können unterbrechen und später weitermachen. → <a href="/formulare/speichern-und-fortsetzen">Details</a></td></tr><tr><td><strong>Automatisch absenden</strong></td><td>Das Formular sendet sich beim Laden selbst ab — etwa um per QR-Code-Scan einen Flow zu starten.</td></tr><tr><td><strong>Absenden-Button ausblenden</strong></td><td>Nützlich, wenn das Formular nur Daten eines Eintrags anzeigen soll.</td></tr><tr><td><strong>Hinweis zur Konto-Bestätigung anzeigen</strong></td><td>Zeigt an, mit welchem Konto die Person angemeldet ist. Sinnvoll an geteilten Geräten.</td></tr><tr><td><strong>Mehrere Sprachen</strong></td><td>Formulartexte in mehreren Sprachen pflegen. → <a href="/formulare/mehrsprachig">Details</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Automatisch absenden braucht vollständige Vorbelegung</p><p>Sendet sich das Formular selbst ab, hat niemand Gelegenheit, Pflichtfelder zu füllen. Alle benötigten Werte müssen also über <em>Vorausgefüllt</em> oder einen vorausgefüllten Link gesetzt sein.</p></div><h2 id="vorschau-und-veroffentlichung" tabindex="-1">Vorschau und Veröffentlichung <a class="header-anchor" href="#vorschau-und-veroffentlichung" aria-label="Permalink to &quot;Vorschau und Veröffentlichung&quot;">​</a></h2><p>Über <strong>Vorschau in neuem Tab</strong> sehen Sie das Formular so, wie Ausfüllende es sehen.</p><p>Zum Verteilen erzeugen Sie mit <strong>Link erstellen</strong> einen Freigabelink. Erst dann ist das Formular erreichbar. Alle Wege dorthin beschreibt <a href="/formulare/formular-teilen">Formular teilen</a>.</p><h2 id="was-ausfullende-sehen" tabindex="-1">Was Ausfüllende sehen <a class="header-anchor" href="#was-ausfullende-sehen" aria-label="Permalink to &quot;Was Ausfüllende sehen&quot;">​</a></h2><p>Zur Orientierung die Beschriftungen im fertigen Formular:</p><table tabindex="0"><thead><tr><th>Element</th><th>Text</th></tr></thead><tbody><tr><td>Absenden</td><td><em>Absenden</em></td></tr><tr><td>Nächste Formularseite</td><td><em>Weiter</em></td></tr><tr><td>Vorherige Formularseite</td><td><em>zurück</em></td></tr><tr><td>Nach dem Absenden</td><td><em>Vielen Dank!</em> / <em>Ihre Antwort ist bei uns eingegangen.</em></td></tr><tr><td>Weitere Antwort</td><td><em>Weitere Antworten senden</em></td></tr><tr><td>Unterschriftsfeld</td><td><em>Hier tippen zum Unterschreiben</em></td></tr><tr><td>Sprachaufnahme</td><td><em>Hier tippen zum Aufnehmen</em></td></tr><tr><td>Fehler</td><td><em>Ups - Fehler</em></td></tr></tbody></table><h2 id="sicherheit" tabindex="-1">Sicherheit <a class="header-anchor" href="#sicherheit" aria-label="Permalink to &quot;Sicherheit&quot;">​</a></h2><p>Auf jedem Formular steht der Hinweis <em>Geben Sie nie Ihr Passwort preis.</em></p><div class="danger custom-block"><p class="custom-block-title">Keine Passwörter oder Zahlungsdaten abfragen</p><p>Fragen Sie über Formulare niemals Passwörter, Zugangsdaten oder vollständige Zahlungsdaten ab. ApptiveGrid weist Ausfüllende ausdrücklich darauf hin, so etwas nicht einzugeben — und blendet bei auffälligen Formularen eine Warnung ein oder sperrt sie.</p><p>Missbräuchliche Formulare lassen sich über <strong>Formular melden</strong> anzeigen. Kontakt: <code>abuse@apptivegrid.com</code>.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/formulare/felder-konfigurieren">Felder konfigurieren</a></li><li><a href="/formulare/mehrseitige-formulare">Mehrseitige Formulare</a></li><li><a href="/formulare/formular-teilen">Formular teilen</a></li><li><a href="/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></li></ul>',53)])])}const c=t(s,[["render",a]]);export{m as __pageData,c as default};
